package com.powercms.cms.delivery;
import com.powercms.cms.delivery.controller.*; import com.powercms.cms.sitepackage.*; import com.powercms.cms.sitepackage.repo.TemplateProjectRepository; import org.springframework.scheduling.annotation.Async; import org.springframework.stereotype.Service; import java.util.*; import java.util.concurrent.*; import java.util.concurrent.atomic.*;
@Service public class CacheWarmupService { private final TemplateProjectRepository projects; private final TemplateService templates; private final SiteControllerRepository controllers; private final RenderDatasetCache cache; private final ExecutorService executor=Executors.newFixedThreadPool(2); private final ConcurrentHashMap<UUID,Status> states=new ConcurrentHashMap<>(); public CacheWarmupService(TemplateProjectRepository p,TemplateService t,SiteControllerRepository c,RenderDatasetCache cache){projects=p;templates=t;controllers=c;this.cache=cache;} public record Status(UUID siteId,String state,int loaded,String message,long startedAt,long finishedAt){} @Async public void trigger(UUID siteId){warm(siteId);}
 public void warm(UUID siteId){long start=System.currentTimeMillis();states.put(siteId,new Status(siteId,"RUNNING",0,null,start,0));executor.submit(()->{int loaded=0;try{for(var p:projects.findBySiteId(siteId)){if(!"FTL".equalsIgnoreCase(p.getProjectType()))continue;for(var f:templates.listFiles(p.getId())){if(f.path().startsWith("site/")||f.path().startsWith("scripts/")||f.path().startsWith("templates/")){cache.getOrLoad(RenderDatasetCache.Region.SYSTEM,p.getId()+":"+f.path(),true,()->f.content());loaded++;}}}for(var c:controllers.findBySiteIdOrderByPathAsc(siteId)){if("PUBLISHED".equals(c.getStatus())){cache.getOrLoad(RenderDatasetCache.Region.APPLICATION,siteId+":"+c.getPath(),true,c::getDefinition);loaded++;}}states.put(siteId,new Status(siteId,"SUCCESS",loaded,null,start,System.currentTimeMillis()));}catch(Exception e){states.put(siteId,new Status(siteId,"FAILED",loaded,"warmup failed",start,System.currentTimeMillis()));}});} public Status status(UUID siteId){return states.getOrDefault(siteId,new Status(siteId,"IDLE",0,null,0,0));} public void shutdown(){executor.shutdownNow();} }
